139:function referenceSummary(draft: Draft) {
140:  const references = [...new Set(draft.blockIds.flatMap((id) => getBlock(id).belegt_in))];
141:  return `${draft.blockIds.join(" · ")}  —  ${references
142:    .map((id) => {
143:      const tenor = register.tenore.find((item) => item.id === id);
144:      return tenor?.zitat_geprueft === true ? id : `${id} ungeprüft`;
145:    })
146:    .join(" · ")}`;
147:}
