123:function debtorFromContext(context: string) {
124:  const match = context.match(
125:    /\b([A-ZÄÖÜ][A-Za-zÄÖÜäöüß0-9&.,' -]{1,100}\s(?:GmbH|AG|UG|SE|KG|e\.\s?K\.))\b/,
126:  );
127:  return match?.[1]?.trim() ?? "die Antragsgegnerin";
128:}
