130:function aiProvenance(response: TenorProposalResponse | null, strategy: "precise" | "neutral") {
131:  const proposal = response?.proposals.find((item) => item.strategy === strategy);
132:  if (!response || !proposal) return null;
133:  const knowledgeLabel = response.reference_version.includes("2026-08-24")
134:    ? "Wissensbasis 24.08.2026"
135:    : response.reference_version;
136:  return `OpenAI ${response.model} · ${knowledgeLabel} · ${proposal.source_ids.length} Quellenanker · nicht juristisch freigegeben`;
137:}
