141:  return `${draft.blockIds.join(" · ")}  —  ${references
142:    .map((id) => {
143:      const tenor = register.tenore.find((item) => item.id === id);
144:      return tenor?.zitat_geprueft === true ? id : `${id} ungeprüft`;
145:    })
146:    .join(" · ")}`;
147:}
148:
149:function DraftChoice({
150:  title,
151:  draft,
152:  text,
153:  selected,
154:  onSelect,
155:  onText,
156:  provenance,
157:  expanded = false,
158:}: {
159:  title: string;
160:  draft: Draft;
161:  text: string;
162:  selected: boolean;
163:  onSelect: () => void;
164:  onText: (text: string) => void;
165:  provenance?: string | null;
166:  expanded?: boolean;
167:}) {
168:  return (
169:    <div
170:      className={`flex min-w-0 flex-col ${
171:        expanded
172:          ? "min-h-[64dvh] flex-1 px-0 py-2 md:min-h-0"
173:          : "px-1 py-4 md:min-h-0 md:px-6 md:py-1"
174:      }`}
175:    >
176:      <button
177:        type="button"
178:        onClick={onSelect}
179:        className={`flex items-center gap-3 text-left ${expanded ? "min-h-11" : ""}`}
180:      >
181:        <span
182:          className={`grid size-5 place-items-center rounded-full border ${selected ? "border-slate-950 bg-slate-950" : "border-slate-300"}`}
183:        >
184:          {selected && <Check className="size-3 text-white" />}
185:        </span>
186:        <span className="text-sm font-semibold text-slate-900">{title}</span>
187:      </button>
188:      <textarea
189:        value={text}
190:        onFocus={onSelect}
191:        onChange={(event) => onText(event.target.value)}
192:        aria-label={`${title} bearbeiten`}
193:        className={`w-full overflow-y-auto bg-transparent font-serif text-slate-700 outline-none ${
194:          expanded
195:            ? "mt-4 min-h-[56dvh] resize-y text-base leading-8 md:min-h-0 md:flex-1"
196:            : "mt-3 min-h-48 resize-none text-sm leading-6 md:min-h-0 md:flex-1"
197:        }`}
198:      />
199:      <p className="mt-3 break-words font-mono text-[9px] leading-4 text-slate-300">
200:        {provenance ?? referenceSummary(draft)}
201:      </p>
202:    </div>
203:  );
204:}
