206:export function MinimalTenorView({ initialArchiveId }: { initialArchiveId?: string | undefined }) {
207:  const [context, setContext] = useState("");
208:  const [mode, setMode] = useState<WritingMode | null>(null);
209:  const [selectedCase, setSelectedCase] = useState<DemoCase | null>(null);
210:  const [commandIndex, setCommandIndex] = useState(0);
211:  const [caseIndex, setCaseIndex] = useState(0);
212:  const [pdf, setPdf] = useState<File | null>(null);
213:  const [pdfExtraction, setPdfExtraction] = useState<TenorPdfExtraction | null>(null);
214:  const [pdfLoading, setPdfLoading] = useState(false);
215:  const [pdfError, setPdfError] = useState("");
216:  const [dragging, setDragging] = useState(false);
217:  const [dictating, setDictating] = useState(false);
218:  const [dictationNotice, setDictationNotice] = useState("");
219:  const [generating, setGenerating] = useState(false);
220:  const [generated, setGenerated] = useState(false);
221:  const [selected, setSelected] = useState<"precise" | "neutral" | null>(null);
222:  const [preciseText, setPreciseText] = useState("");
223:  const [neutralText, setNeutralText] = useState("");
224:  const [proposalResponse, setProposalResponse] = useState<TenorProposalResponse | null>(null);
225:  const [generationError, setGenerationError] = useState("");
226:  const [archiveError, setArchiveError] = useState("");
227:  const [savingArchive, setSavingArchive] = useState(false);
228:  const [activeArchive, setActiveArchive] = useState<TenorArchiveRecord | null>(null);
229:  const [archiveLoading, setArchiveLoading] = useState(false);
230:  const [archiveLoadError, setArchiveLoadError] = useState("");
231:  const [requiredIntakeAnswers, setRequiredIntakeAnswers] = useState<RequiredIntakeAnswer[]>([]);
232:  const [requiredIntakeAnswer, setRequiredIntakeAnswer] = useState("");
233:  const [revisionInput, setRevisionInput] = useState("");
234:  const [revisionHistory, setRevisionHistory] = useState<string[]>([]);
235:  const [lastGenerationContext, setLastGenerationContext] = useState("");
236:  const [clarificationTurns, setClarificationTurns] = useState<ClarificationTurn[]>([]);
237:  const [currentQuestion, setCurrentQuestion] = useState<TenorQuestion | null>(null);
238:  const [questionLoading, setQuestionLoading] = useState(false);
239:  const [clarificationReady, setClarificationReady] = useState(false);
240:  const [questionError, setQuestionError] = useState("");
241:  const [textAnswer, setTextAnswer] = useState("");
242:  const [customChoiceOpen, setCustomChoiceOpen] = useState(false);
243:  const [sliderAnswer, setSliderAnswer] = useState(0);
244:  const [acceptedIds, setAcceptedIds] = useState<string[]>([]);
245:  const [suggestion, setSuggestion] = useState<ReturnType<typeof nextAutofillBlock>>(null);
246:  const fileInput = useRef<HTMLInputElement>(null);
247:  const contextInput = useRef<HTMLTextAreaElement>(null);
248:  const speech = useRef<SpeechRecognitionInstance | null>(null);
249:  const dictationBase = useRef("");
250:  const dictationSegments = useRef<DictationSegments>({});
251:  const dictationSession = useRef(0);
252:  const pdfSession = useRef(0);
253:  const questionSession = useRef(0);
254:  const sourceContext = useMemo(
255:    () => composePdfContext(context, pdfExtraction),
256:    [context, pdfExtraction],
257:  );
258:  const previousSourceContext = useRef(sourceContext);
259:
260:  const factualContext = useMemo(
261:    () =>
262:      [
263:        sourceContext,
264:        ...requiredIntakeAnswers.map((item) => `${item.question}\nAntwort: ${item.answer}`),
265:      ]
266:        .filter(Boolean)
267:        .join("\n\n"),
268:    [requiredIntakeAnswers, sourceContext],
269:  );
270:
271:  const clarifiedContext = useMemo(
272:    () => composeClarifiedContext(factualContext, clarificationTurns),
273:    [clarificationTurns, factualContext],
274:  );
275:  const profile = useMemo(
276:    () => profileFromContext(clarifiedContext, Boolean(pdfExtraction)),
277:    [clarifiedContext, pdfExtraction],
278:  );
279:  const preciseDraft = useMemo(() => composeDraft(profile, "eng"), [profile]);
280:  const neutralDraft = useMemo(() => composeDraft(profile, "kerngleich"), [profile]);
281:  const contextLength = sourceContext.length;
282:  const correctionMode = mode === "tenor" || isTenor(sourceContext);
283:  const requiredIntakeFact = correctionMode
284:    ? null
285:    : nextRequiredIntakeFact(sourceContext, profile.fallgruppe, requiredIntakeAnswers);
286:  const slashMatch = context.match(/(?:^|\s)\/([^\s]*)$/);
287:  const slashQuery = slashMatch?.[1]?.toLocaleLowerCase("de") ?? "";
288:  const showModeMenu = Boolean(slashMatch);
289:  const filteredCommands = filterModeCommands(slashQuery);
290:  const normalizedCaseQuery = context.trim().toLocaleLowerCase("de");
291:  const caseMatches =
292:    mode === "fälle" && !selectedCase
293:      ? lottoDemoCases
294:          .filter((item) =>
295:            `${item.title} ${item.fall_id} ${item.domain} ${item.secondary}`
296:              .toLocaleLowerCase("de")
297:              .includes(normalizedCaseQuery),
298:          )
299:          .slice(0, 5)
300:      : [];
301:  const canRequestQuestions =
302:    !showModeMenu &&
303:    !correctionMode &&
304:    (mode !== "fälle" || Boolean(selectedCase)) &&
305:    contextLength >= 20 &&
306:    !pdfLoading &&
307:    !requiredIntakeFact &&
308:    !clarificationReady;
309:  const canGenerate =
310:    !showModeMenu &&
311:    !correctionMode &&
312:    !pdfLoading &&
313:    clarificationReady &&
314:    (Boolean(selectedCase) || clarifiedContext.length >= 20);
315:
316:  useEffect(() => {
317:    if (!initialArchiveId) return;
318:    let cancelled = false;
319:    setArchiveLoading(true);
320:    setArchiveLoadError("");
321:    void listTenorArchiveEntries()
322:      .then(({ tenors }) => {
323:        if (cancelled) return;
324:        const archivedTenor = tenors.find((item) => item.tenor_id === initialArchiveId);
325:        if (!archivedTenor) {
326:          setArchiveLoadError("Der archivierte Tenor wurde nicht gefunden.");
327:          return;
328:        }
329:        setActiveArchive(archivedTenor);
330:        setMode("tenor");
331:        setContext(archivedTenor.text);
332:        setSelectedCase(null);
333:        setGenerated(false);
334:        setRevisionInput("");
335:        setRevisionHistory([]);
336:        setLastGenerationContext("");
337:      })
338:      .catch((error: unknown) => {
339:        if (cancelled) return;
340:        setArchiveLoadError(
341:          error instanceof Error ? error.message : "Das Tenorarchiv konnte nicht geladen werden.",
342:        );
343:      })
344:      .finally(() => {
345:        if (!cancelled) setArchiveLoading(false);
346:      });
347:    return () => {
348:      cancelled = true;
349:    };
350:  }, [initialArchiveId]);
351:
352:  useEffect(() => {
353:    if (!correctionMode || generated || context.trim().length < 4) {
354:      setSuggestion(null);
355:      return;
356:    }
357:    const timer = window.setTimeout(
358:      () => setSuggestion(nextAutofillBlock(profile, acceptedIds)),
359:      800,
360:    );
580:  const answerRequiredIntakeFact = () => {
581:    const answer = requiredIntakeAnswer.trim();
582:    if (!requiredIntakeFact || !answer) return;
583:    setRequiredIntakeAnswers((current) => [
584:      ...current.filter((item) => item.id !== requiredIntakeFact.id),
585:      { ...requiredIntakeFact, answer },
586:    ]);
587:    setRequiredIntakeAnswer("");
588:  };
589:
590:  const generateProposals = async (generationContext: string) => {
591:    if (generating || generationContext.trim().length < 4) return;
592:    setGenerating(true);
593:    setGenerationError("");
594:    setSuggestion(null);
595:    setLastGenerationContext(generationContext);
596:    try {
597:      const legalBases = extractLegalBases(generationContext);
598:      const legalBasisStillOpen = requiredIntakeAnswers.some(
599:        (item) => item.id === "rechtsgrundlagen" && extractLegalBases(item.answer).length === 0,
600:      );
601:      const response = await createTenorProposals({
602:        fall_id: activeArchive?.fall_id ?? selectedCase?.fall_id ?? "TENOR-ENTWURF",
603:        schuldner: activeArchive?.schuldner ?? debtorFromContext(generationContext),
604:        fundstelle:
605:          selectedCase?.url ??
606:          generationContext.match(/https?:\/\/[^\s,;)]+/i)?.[0] ??
607:          (pdfExtraction
608:            ? `Hochgeladenes Vertragsdokument: ${pdfExtraction.filename}`
609:            : "Vom Nutzer beschriebene Fundstelle"),
610:        context: generationContext,
611:        fallgruppe: profile.fallgruppe,
612:        rechtsgrundlagen:
613:          legalBases.length > 0
614:            ? legalBases
615:            : legalBasisStillOpen
616:              ? ["Rechtsgrundlage noch durch Menschen zu prüfen"]
617:              : legalBasesFor(profile.fallgruppe),
618:      });
619:      const precise = response.proposals.find((item) => item.strategy === "precise");
620:      const neutral = response.proposals.find((item) => item.strategy === "neutral");
621:      if (!precise || !neutral) throw new Error("Die KI hat nicht beide Entwürfe geliefert.");
622:      setProposalResponse(response);
623:      setPreciseText(precise.text);
624:      setNeutralText(neutral.text);
625:      setSelected(null);
626:      setGenerated(true);
627:    } catch (error) {
628:      setProposalResponse(null);
629:      setGenerationError(
630:        error instanceof Error ? error.message : "Die KI-Entwürfe konnten nicht erzeugt werden.",
631:      );
632:    } finally {
633:      setGenerating(false);
634:    }
635:  };
636:
637:  const generate = () => {
638:    if (!canGenerate) return;
639:    void generateProposals(clarifiedContext);
640:  };
641:
642:  const submitRevision = () => {
643:    const instruction = revisionInput.trim();
644:    if (!instruction || generating || context.trim().length < 4) return;
645:    const revisionContext = composeRevisionContext(
646:      context,
647:      instruction,
648:      activeArchive?.context ?? "",
649:    );
650:    setRevisionHistory((current) => [...current, instruction]);
651:    setRevisionInput("");
652:    void generateProposals(revisionContext);
653:  };
654:
655:  const reset = () => {
656:    setContext("");
657:    setMode(null);
658:    setSelectedCase(null);
659:    setCommandIndex(0);
660:    setCaseIndex(0);
661:    pdfSession.current += 1;
662:    setPdf(null);
663:    setPdfExtraction(null);
664:    setPdfLoading(false);
665:    setPdfError("");
666:    setGenerated(false);
667:    setSelected(null);
668:    setProposalResponse(null);
669:    setGenerationError("");
670:    setArchiveError("");
671:    setSavingArchive(false);
672:    setActiveArchive(null);
673:    setArchiveLoading(false);
674:    setArchiveLoadError("");
675:    setRequiredIntakeAnswers([]);
676:    setRequiredIntakeAnswer("");
677:    setRevisionInput("");
678:    setRevisionHistory([]);
679:    setLastGenerationContext("");
680:    questionSession.current += 1;
681:    setClarificationTurns([]);
682:    setCurrentQuestion(null);
683:    setQuestionLoading(false);
684:    setClarificationReady(false);
685:    setQuestionError("");
686:    setTextAnswer("");
687:    setCustomChoiceOpen(false);
688:    setAcceptedIds([]);
689:    setSuggestion(null);
690:  };
691:
692:  const adoptSelected = async () => {
693:    if (!selected || savingArchive) return;
694:    const draft = selected === "precise" ? preciseDraft : neutralDraft;
695:    const text = selected === "precise" ? preciseText : neutralText;
696:    const proposal = proposalResponse?.proposals.find((item) => item.strategy === selected);
697:    const schuldner = activeArchive?.schuldner ?? debtorFromContext(lastGenerationContext);
698:    setArchiveError("");
699:    setSavingArchive(true);
700:    try {
701:      const archivedTenor = await saveTenorArchiveEntry({
702:        fall_id: activeArchive?.fall_id ?? selectedCase?.fall_id ?? "TENOR-ENTWURF",
703:        schuldner,
704:        title: activeArchive?.title ?? selectedCase?.title ?? schuldner,
705:        text,
706:        context: lastGenerationContext.trim() || clarifiedContext.trim(),
707:        strategy: selected,
708:        model: proposalResponse?.model ?? "Lokale Bausteinlogik",
709:        reference_version: proposalResponse?.reference_version ?? "Lokales Tenorregister",
710:        source_ids: proposal?.source_ids ?? draft.blockIds,
711:      });
712:      setContext(text);
713:      setActiveArchive(archivedTenor);
714:      setAcceptedIds(draft.blockIds);
715:      setGenerated(false);
716:      setSelected(null);
717:    } catch (error) {
718:      setArchiveError(
719:        error instanceof Error ? error.message : "Der Tenor konnte nicht archiviert werden.",
720:      );
721:    } finally {
722:      setSavingArchive(false);
723:    }
724:  };
725:
726:  return (
727:    <div
728:      className={`min-h-[calc(100dvh-4rem)] bg-white transition-colors ${dragging ? "bg-blue-50/40" : ""}`}
729:      onDragOver={(event) => {
730:        event.preventDefault();
1250:              >
1251:                <span>{questionError}</span>
1252:                <button
1253:                  type="button"
1254:                  onClick={() => void requestClarificationQuestion()}
1255:                  className="rounded-full border border-red-200 px-3 py-1.5 font-semibold"
1256:                >
1257:                  Erneut versuchen
1258:                </button>
1259:              </div>
1260:            )}
1261:            {suggestion && (
1262:              <button
1263:                type="button"
1264:                onClick={(event) => {
1265:                  event.stopPropagation();
1266:                  acceptSuggestion();
1267:                }}
1268:                className="mt-3 flex items-start gap-3 text-left text-sm leading-6 text-slate-300 transition hover:text-slate-500"
1269:              >
1270:                <span className="mt-1 flex shrink-0 items-center gap-1 font-mono text-[10px] text-slate-400">
1271:                  <Keyboard className="size-3" />
1272:                  Tab
1273:                </span>
1274:                <span>{suggestion.text.replace(/\s+/g, " ")}</span>
1275:              </button>
1276:            )}
1277:          </div>
1278:
1279:          <div className="fixed inset-x-0 bottom-0 z-20 border-t border-slate-100 bg-white/95 backdrop-blur">
1280:            <div className="mx-auto flex min-h-20 max-w-4xl items-center justify-between px-6">
1281:              <div className="flex items-center gap-1">
1282:                <button
1283:                  type="button"
1284:                  onClick={() => fileInput.current?.click()}
1285:                  aria-label="PDF hochladen"
1286:                  className="rounded-full p-3 text-slate-300 transition hover:bg-slate-50 hover:text-slate-700"
1287:                >
1288:                  <FileUp className="size-5" />
1289:                </button>
1290:                <button
1291:                  type="button"
1292:                  onClick={toggleDictation}
1293:                  aria-label={dictating ? "Diktat beenden" : "Sachverhalt diktieren"}
1294:                  className={`rounded-full p-3 transition ${dictating ? "bg-red-50 text-red-500" : "text-slate-300 hover:bg-slate-50 hover:text-slate-700"}`}
1295:                >
1296:                  <Mic className="size-5" />
1297:                </button>
1298:                <input
1299:                  ref={fileInput}
1300:                  type="file"
1301:                  accept="application/pdf,.pdf"
1302:                  className="hidden"
1303:                  onChange={(event) => {
1304:                    const file = event.currentTarget.files?.[0];
1305:                    event.currentTarget.value = "";
1306:                    void acceptPdf(file);
1307:                  }}
1308:                />
1309:                {correctionMode && (
1310:                  <span className="ml-2 text-[10px] uppercase tracking-wider text-slate-300">
1311:                    Tenor erkannt · Korrekturmodus
1312:                  </span>
1313:                )}
1314:                {dictationNotice && (
1315:                  <span className="ml-2 text-xs text-slate-400">{dictationNotice}</span>
1316:                )}
1317:                {generationError && !correctionMode && (
1318:                  <span role="alert" className="ml-2 max-w-md text-xs text-red-600">
1319:                    {generationError}
1320:                  </span>
1321:                )}
1322:              </div>
1323:              {canRequestQuestions &&
1324:                !currentQuestion &&
1325:                !questionLoading &&
1326:                !questionError &&
1327:                clarificationTurns.length === 0 && (
1328:                  <button
1329:                    type="button"
1330:                    onClick={() => void requestClarificationQuestion()}
1331:                    className="flex items-center gap-2 rounded-full bg-slate-950 px-5 py-2.5 text-sm font-semibold text-white transition hover:bg-slate-800"
1332:                  >
1333:                    <Sparkles className="size-4" />
1334:                    KI-Rückfragen starten
1335:                  </button>
1336:                )}
1337:              {canGenerate && (
1338:                <button
1339:                  type="button"
1340:                  onClick={generate}
1341:                  disabled={generating}
1342:                  aria-busy={generating}
1343:                  className="flex items-center gap-2 rounded-full bg-slate-950 px-5 py-2.5 text-sm font-semibold text-white transition hover:bg-slate-800 disabled:opacity-60"
1344:                >
1345:                  {generating ? (
1346:                    <Loader2 className="size-4 animate-spin" />
1347:                  ) : (
1348:                    <Sparkles className="size-4" />
1349:                  )}
1350:                  <span aria-live="polite">
1351:                    {generating ? "KI erstellt zwei Entwürfe …" : "Generieren"}
1352:                  </span>
1353:                </button>
1354:              )}
1355:            </div>
1356:          </div>
1357:        </main>
1358:      ) : (
1359:        <main
1360:          className={`mx-auto flex max-w-6xl flex-col px-6 py-8 md:py-6 ${
1361:            selected
1362:              ? "md:h-[calc(100dvh-2rem)] md:min-h-[38rem]"
1363:              : "md:h-[calc(100dvh-8rem)] md:min-h-[30rem]"
1364:          }`}
1365:        >
1366:          {selected ? (
1367:            <>
1368:              <div className="flex items-center justify-between gap-4">
1369:                <button
1370:                  type="button"
1371:                  onClick={() => setSelected(null)}
1372:                  className="flex items-center gap-2 text-sm text-slate-400 transition hover:text-slate-800"
1373:                >
1374:                  <ArrowLeft className="size-4" /> Beide Entwürfe
1375:                </button>
1376:                <span className="text-xs text-slate-300">Breite Lese- und Bearbeitungsansicht</span>
1377:              </div>
1378:              <div className="mx-auto mt-4 flex min-h-[64dvh] w-full max-w-5xl flex-1 flex-col md:min-h-0">
1379:                <DraftChoice
1380:                  title={selected === "precise" ? "Präzise" : "Technikneutral"}
1381:                  draft={selected === "precise" ? preciseDraft : neutralDraft}
1382:                  text={selected === "precise" ? preciseText : neutralText}
1383:                  selected
1384:                  onSelect={() => undefined}
1385:                  onText={selected === "precise" ? setPreciseText : setNeutralText}
1386:                  provenance={aiProvenance(proposalResponse, selected)}
1387:                  expanded
1388:                />
1389:              </div>
1390:              <div className="mt-4 flex min-h-11 items-center justify-center">
1391:                <div className="text-center">
1392:                  {archiveError && (
1393:                    <p role="alert" className="mb-3 text-xs text-red-600">
1394:                      {archiveError}
1395:                    </p>
1396:                  )}
1397:                  <button
1398:                    type="button"
1399:                    onClick={() => void adoptSelected()}
1400:                    disabled={savingArchive}
1401:                    aria-busy={savingArchive}
1402:                    className="inline-flex items-center gap-2 rounded-full bg-slate-950 px-6 py-2.5 text-sm font-semibold text-white disabled:opacity-60"
1403:                  >
1404:                    {savingArchive && <Loader2 className="size-4 animate-spin" />}
1405:                    {savingArchive ? "Wird archiviert …" : "Entwurf übernehmen"}
1406:                  </button>
1407:                </div>
1408:              </div>
1409:            </>
1410:          ) : (
1411:            <>
1412:              <h1 className="text-center font-sans text-sm font-medium text-slate-400">
1413:                Wähle einen Entwurf
1414:              </h1>
1415:              <div className="mt-5 grid md:min-h-0 md:flex-1 md:grid-cols-2 md:divide-x md:divide-slate-100">
1416:                <DraftChoice
1417:                  title="Präzise"
1418:                  draft={preciseDraft}
1419:                  text={preciseText}
1420:                  selected={false}
1421:                  onSelect={() => setSelected("precise")}
1422:                  onText={setPreciseText}
1423:                  provenance={aiProvenance(proposalResponse, "precise")}
1424:                />
1425:                <DraftChoice
1426:                  title="Technikneutral"
1427:                  draft={neutralDraft}
1428:                  text={neutralText}
1429:                  selected={false}
1430:                  onSelect={() => setSelected("neutral")}
1431:                  onText={setNeutralText}
1432:                  provenance={aiProvenance(proposalResponse, "neutral")}
1433:                />
1434:              </div>
1435:              <div className="mt-4 min-h-11" />
1436:            </>
1437:          )}
1438:        </main>
1439:      )}
1440:    </div>
1441:  );
