                        {item.title}
                      </span>
                      <span className="ml-auto shrink-0 font-mono text-[9px] text-slate-300">
                        {item.fall_id}
                      </span>
                    </button>
                  ))
                ) : (
                  <p className="px-3 py-2 text-xs text-slate-400">Kein Fall gefunden.</p>
                )}
              </div>
            )}
            {requiredIntakeFact && contextLength >= 20 && !showModeMenu && (
