import { Link } from "@tanstack/react-router";
import {
  ArrowLeft,
  Check,
  FileUp,
  Keyboard,
  Loader2,
  Mic,
  RotateCcw,
  Send,
  Sparkles,
  X,
} from "lucide-react";
import { useEffect, useMemo, useRef, useState } from "react";

import { composeDraft, getBlock, nextAutofillBlock, register } from "@/tenor-engine";
import type { Draft, Profile } from "@/tenor-types";
import { lottoDemoCases, type DemoCase } from "@/data/lottoDemoCases";
import {
  composeRevisionContext,
  extractLegalBases,
  filterModeCommands,
  inferFallgruppe,
  isTenor,
  modeCommands,
  nextRequiredIntakeFact,
  nextWrappedIndex,
  type RequiredIntakeAnswer,
  type WritingMode,
} from "@/lib/minimal-tenor-logic";
import {
  composeDictationText,
  mergeDictationSegments,
  type DictationSegments,
} from "@/lib/dictation";
import {
  createTenorProposals,
  createTenorQuestion,
  extractTenorPdf,
  listTenorArchiveEntries,
  saveTenorArchiveEntry,
  type TenorArchiveRecord,
  type TenorPdfExtraction,
  type TenorProposalResponse,
  type TenorQuestion,
} from "@/lib/tenor-api";
import {
  answeredQuestions,
  composeClarifiedContext,
  composePdfContext,
  formatSliderAnswer,
  type ClarificationTurn,
} from "@/lib/tenor-questions";
import { Slider } from "@/components/ui/slider";

const baseProfile: Profile = {
  profilId: "V-2026-014",
  schuldner: "die Beklagte",
  rechtsform: "GmbH",
  kanal: ["website"],
  url: "https://www.beispiel.de",
  adressat: "verbraucher",
  vertragstyp: "dauerschuldverhaeltnis",
  fallgruppe: "kuendigungsbutton",
  verstossModus: "vorhanden_unzureichend",
  rechtsgrundlage: ["§ 2 Abs. 1 UKlaG", "§ 312k Abs. 2 BGB", "§ 890 ZPO"],
  beanstandeterWortlaut: "",
  wirkung: "",
  bekannteUmgehungen: [],
  gestaltungsmerkmale: ["Gestaltung", "Wirkung"],
  anlage: "K 1",
};

type SpeechResult = { readonly transcript: string };
type SpeechResultList = {
  readonly length: number;
  [index: number]: { readonly isFinal: boolean; [index: number]: SpeechResult };
};
type SpeechEvent = { readonly resultIndex: number; readonly results: SpeechResultList };
type SpeechRecognitionInstance = {
  lang: string;
  continuous: boolean;
  interimResults: boolean;
  onresult: ((event: SpeechEvent) => void) | null;
  onend: (() => void) | null;
  start: () => void;
  stop: () => void;
};
type SpeechRecognitionConstructor = new () => SpeechRecognitionInstance;
function caseContext(selectedCase: DemoCase) {
  return `${selectedCase.fall_id}: ${selectedCase.title}. ${selectedCase.secondary}. ${selectedCase.explanation} Fundstelle: ${selectedCase.evidence.fundstelle}.`;
}

function profileFromContext(context: string, uploadedContract = false): Profile {
  const lower = context.toLowerCase();
  const fallgruppe = inferFallgruppe(lower, uploadedContract);
  const verstossModus =
    fallgruppe === "agb_klausel"
      ? "klausel_verwendet"
      : fallgruppe === "kuendigungsbutton"
        ? "vorhanden_unzureichend"
        : "irrefuehrend_gestaltet";
  const url = context.match(/https?:\/\/[^\s,;)]+/i)?.[0] ?? baseProfile.url;
  return {
    ...baseProfile,
    fallgruppe,
    verstossModus,
    url,
    kanal: /\bapp\b/i.test(context) ? ["website", "app"] : ["website"],
    beanstandeterWortlaut: fallgruppe === "agb_klausel" ? context.slice(0, 500) : "",
    wirkung: context.slice(0, 500),
  };
}

function legalBasesFor(fallgruppe: string) {
  if (fallgruppe === "agb_klausel") return ["§ 1 UKlaG"];
  if (fallgruppe === "irrefuehrende_werbung") return ["§ 5 UWG", "§ 8 Abs. 1 UWG"];
  if (fallgruppe === "consent_gestaltung") return ["§ 25 Abs. 1 TDDDG", "§ 2 Abs. 1 UKlaG"];
  if (fallgruppe === "dark_pattern_dsa") return ["Art. 25 DSA", "§ 2 Abs. 1 UKlaG"];
  return ["§ 312k Abs. 2 BGB", "§ 2 Abs. 1 UKlaG"];
}

function debtorFromContext(context: string) {
  const match = context.match(
    /\b([A-ZÄÖÜ][A-Za-zÄÖÜäöüß0-9&.,' -]{1,100}\s(?:GmbH|AG|UG|SE|KG|e\.\s?K\.))\b/,
  );
  return match?.[1]?.trim() ?? "die Antragsgegnerin";
}

function aiProvenance(response: TenorProposalResponse | null, strategy: "precise" | "neutral") {
  const proposal = response?.proposals.find((item) => item.strategy === strategy);
  if (!response || !proposal) return null;
  const knowledgeLabel = response.reference_version.includes("2026-08-24")
    ? "Wissensbasis 24.08.2026"
    : response.reference_version;
  return `OpenAI ${response.model} · ${knowledgeLabel} · ${proposal.source_ids.length} Quellenanker · nicht juristisch freigegeben`;
}

function referenceSummary(draft: Draft) {
  const references = [...new Set(draft.blockIds.flatMap((id) => getBlock(id).belegt_in))];
  return `${draft.blockIds.join(" · ")}  —  ${references
    .map((id) => {
      const tenor = register.tenore.find((item) => item.id === id);
      return tenor?.zitat_geprueft === true ? id : `${id} ungeprüft`;
    })
    .join(" · ")}`;
}

function DraftChoice({
  title,
  draft,
  text,
  selected,
  onSelect,
  onText,
  provenance,
  expanded = false,
}: {
  title: string;
  draft: Draft;
  text: string;
  selected: boolean;
  onSelect: () => void;
  onText: (text: string) => void;
  provenance?: string | null;
  expanded?: boolean;
}) {
  return (
    <div
      className={`flex min-w-0 flex-col ${
        expanded
          ? "min-h-[64dvh] flex-1 px-0 py-2 md:min-h-0"
          : "px-1 py-4 md:min-h-0 md:px-6 md:py-1"
      }`}
    >
      <button
        type="button"
        onClick={onSelect}
        className={`flex items-center gap-3 text-left ${expanded ? "min-h-11" : ""}`}
      >
          error instanceof Error ? error.message : "Das Tenorarchiv konnte nicht geladen werden.",
        );
      })
      .finally(() => {
        if (!cancelled) setArchiveLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [initialArchiveId]);

  useEffect(() => {
    if (!correctionMode || generated || context.trim().length < 4) {
      setSuggestion(null);
      return;
    }
    const timer = window.setTimeout(
      () => setSuggestion(nextAutofillBlock(profile, acceptedIds)),
      800,
    );
    return () => window.clearTimeout(timer);
  }, [acceptedIds, context, correctionMode, generated, profile]);

  useEffect(() => {
    setCommandIndex(0);
  }, [slashQuery]);

  useEffect(() => {
    setCaseIndex(0);
  }, [normalizedCaseQuery]);

  useEffect(() => {
    const input = contextInput.current;
    if (!input) return;
    input.style.height = "0px";
    input.style.height = `${Math.max(input.scrollHeight, 36)}px`;
  }, [context, pdf]);

  useEffect(() => {
    if (previousSourceContext.current === sourceContext) return;
    previousSourceContext.current = sourceContext;
    questionSession.current += 1;
    setClarificationTurns([]);
    setCurrentQuestion(null);
    setQuestionLoading(false);
    setClarificationReady(false);
    setQuestionError("");
    setTextAnswer("");
    setCustomChoiceOpen(false);
    setRequiredIntakeAnswers([]);
    setRequiredIntakeAnswer("");
  }, [sourceContext]);

  useEffect(
    () => () => {
      dictationSession.current += 1;
      pdfSession.current += 1;
      speech.current?.stop();
    },
    [],
  );

  const acceptPdf = async (file?: File) => {
    if (!file) return;
    const session = pdfSession.current + 1;
    pdfSession.current = session;
    if (file.type !== "application/pdf" && !file.name.toLowerCase().endsWith(".pdf")) {
      setPdf(null);
      setPdfExtraction(null);
      setPdfLoading(false);
      setPdfError("Bitte eine PDF-Datei auswählen.");
      return;
    }
    if (file.size > 10 * 1024 * 1024) {
      setPdf(file);
      setPdfExtraction(null);
      setPdfLoading(false);
      setPdfError("Die PDF-Datei darf höchstens 10 MB groß sein.");
      return;
    }
    setPdf(file);
    setPdfExtraction(null);
    setPdfLoading(true);
    setPdfError("");
    setGenerated(false);
    setGenerationError("");
    try {
      const extraction = await extractTenorPdf(file);
      if (pdfSession.current !== session) return;
      setPdfExtraction(extraction);
    } catch (error) {
      if (pdfSession.current !== session) return;
      setPdfError(
        error instanceof Error ? error.message : "Der PDF-Text konnte nicht gelesen werden.",
      );
    } finally {
      if (pdfSession.current === session) setPdfLoading(false);
    }
  };

  const removePdf = () => {
    pdfSession.current += 1;
    setPdf(null);
    setPdfExtraction(null);
    setPdfLoading(false);
    setPdfError("");
  };

  const selectMode = (nextMode: WritingMode) => {
    const contextWithoutCommand = context.replace(/(?:^|\s)\/[^\s]*$/, "").trimEnd();
    setMode(nextMode);
    setSelectedCase(null);
    setActiveArchive(null);
    setRevisionInput("");
    setRevisionHistory([]);
    setContext(nextMode === "fälle" ? "" : contextWithoutCommand);
    setCommandIndex(0);
    setCaseIndex(0);
    setGenerated(false);
    setSuggestion(null);
    setGenerationError("");
    window.requestAnimationFrame(() => contextInput.current?.focus());
  };

  const chooseCase = (item: DemoCase) => {
    setMode("fälle");
    setSelectedCase(item);
    setActiveArchive(null);
    setCaseIndex(0);
    setContext(caseContext(item));
    setGenerated(false);
    setSuggestion(null);
    setGenerationError("");
    window.requestAnimationFrame(() => contextInput.current?.focus());
  };

  const toggleDictation = () => {
    if (dictating) {
      speech.current?.stop();
      setDictating(false);
      return;
    }
    const browserWindow = window as typeof window & {
      SpeechRecognition?: SpeechRecognitionConstructor;
      webkitSpeechRecognition?: SpeechRecognitionConstructor;
    };
    const Recognition = browserWindow.SpeechRecognition ?? browserWindow.webkitSpeechRecognition;
    if (!Recognition) {
      setDictationNotice("Diktat wird von diesem Browser nicht unterstützt.");
      return;
    }
    const recognition = new Recognition();
    const session = dictationSession.current + 1;
    dictationSession.current = session;
    dictationBase.current = context;
    dictationSegments.current = {};
    recognition.lang = "de-DE";
    recognition.continuous = true;
    recognition.interimResults = true;
    recognition.onresult = (event) => {
      if (dictationSession.current !== session) return;
      const updates = [];
      for (let index = event.resultIndex; index < event.results.length; index += 1) {
        const result = event.results[index];
        updates.push({
          index,
          transcript: result?.[0]?.transcript ?? "",
          isFinal: result?.isFinal ?? false,
        });
      }
      dictationSegments.current = mergeDictationSegments(dictationSegments.current, updates);
      setContext(composeDictationText(dictationBase.current, dictationSegments.current));
    };
    recognition.onend = () => {
      if (dictationSession.current !== session) return;
      speech.current = null;
      setDictating(false);
    };
    speech.current = recognition;
    setDictationNotice("");
    setDictating(true);
    recognition.start();
  };

  const acceptSuggestion = () => {
    if (!suggestion) return;
    setContext((current) => `${current.trim()} ${suggestion.text.replace(/\s+/g, " ").trim()}`);
    setAcceptedIds((current) => [...current, suggestion.id]);
    setSuggestion(null);
  };

  const requestClarificationQuestion = async (turns = clarificationTurns) => {
    if (sourceContext.length < 20 || questionLoading || pdfLoading) return;
    const session = questionSession.current + 1;
    questionSession.current = session;
    setQuestionLoading(true);
    setQuestionError("");
    setCurrentQuestion(null);
    try {
      const response = await createTenorQuestion({
        context: factualContext,
        fallgruppe: profile.fallgruppe,
        answered_questions: answeredQuestions(turns),
      });
      if (questionSession.current !== session) return;
      if (response.ready_to_generate) {
        setClarificationReady(true);
        return;
      }
      if (!response.question) throw new Error("Die KI hat keine Rückfrage geliefert.");
      setCurrentQuestion(response.question);
      setTextAnswer("");
      setCustomChoiceOpen(false);
      if (response.question.slider) {
        const { minimum, maximum, step } = response.question.slider;
        const steps = Math.floor((maximum - minimum) / step);
        setSliderAnswer(minimum + Math.floor(steps / 2) * step);
      }
    } catch (error) {
      if (questionSession.current !== session) return;
      setQuestionError(
        error instanceof Error ? error.message : "Die KI-Rückfrage konnte nicht erzeugt werden.",
      );
    } finally {
      if (questionSession.current === session) setQuestionLoading(false);
    }
  };

  const answerCurrentQuestion = (answer: string) => {
    const cleanedAnswer = answer.trim();
    if (!currentQuestion || !cleanedAnswer || questionLoading) return;
    const nextTurns = [...clarificationTurns, { question: currentQuestion, answer: cleanedAnswer }];
    setClarificationTurns(nextTurns);
    setCurrentQuestion(null);
    setTextAnswer("");
    setCustomChoiceOpen(false);
    void requestClarificationQuestion(nextTurns);
  };

  const answerRequiredIntakeFact = () => {
    const answer = requiredIntakeAnswer.trim();
    if (!requiredIntakeFact || !answer) return;
    setRequiredIntakeAnswers((current) => [
      ...current.filter((item) => item.id !== requiredIntakeFact.id),
      { ...requiredIntakeFact, answer },
    ]);
    setRequiredIntakeAnswer("");
  };

  const generateProposals = async (generationContext: string) => {
    if (generating || generationContext.trim().length < 4) return;
    setGenerating(true);
    setGenerationError("");
    setSuggestion(null);
    setLastGenerationContext(generationContext);
    try {
      const legalBases = extractLegalBases(generationContext);
      const legalBasisStillOpen = requiredIntakeAnswers.some(
        (item) => item.id === "rechtsgrundlagen" && extractLegalBases(item.answer).length === 0,
      );
      const response = await createTenorProposals({
        fall_id: activeArchive?.fall_id ?? selectedCase?.fall_id ?? "TENOR-ENTWURF",
        schuldner: activeArchive?.schuldner ?? debtorFromContext(generationContext),
        fundstelle:
          selectedCase?.url ??
          generationContext.match(/https?:\/\/[^\s,;)]+/i)?.[0] ??
          (pdfExtraction
            ? `Hochgeladenes Vertragsdokument: ${pdfExtraction.filename}`
            : "Vom Nutzer beschriebene Fundstelle"),
        context: generationContext,
        fallgruppe: profile.fallgruppe,
        rechtsgrundlagen:
          legalBases.length > 0
            ? legalBases
            : legalBasisStillOpen
              ? ["Rechtsgrundlage noch durch Menschen zu prüfen"]
              : legalBasesFor(profile.fallgruppe),
      });
      const precise = response.proposals.find((item) => item.strategy === "precise");
      const neutral = response.proposals.find((item) => item.strategy === "neutral");
      if (!precise || !neutral) throw new Error("Die KI hat nicht beide Entwürfe geliefert.");
      setProposalResponse(response);
      setPreciseText(precise.text);
      setNeutralText(neutral.text);
      setSelected(null);
      setGenerated(true);
    } catch (error) {
      setProposalResponse(null);
      setGenerationError(
        error instanceof Error ? error.message : "Die KI-Entwürfe konnten nicht erzeugt werden.",
      );
    } finally {
      setGenerating(false);
    }
  };

  const generate = () => {
    if (!canGenerate) return;
    void generateProposals(clarifiedContext);
  };

  const submitRevision = () => {
    const instruction = revisionInput.trim();
    if (!instruction || generating || context.trim().length < 4) return;
    const revisionContext = composeRevisionContext(
      context,
      instruction,
      activeArchive?.context ?? "",
    );
    setRevisionHistory((current) => [...current, instruction]);
            )}
            {mode === "fälle" && !selectedCase && !showModeMenu && (
              <div
                role="listbox"
                aria-label="Fall auswählen"
                className="ml-14 mt-1 max-w-sm overflow-hidden rounded-lg border border-slate-200 bg-white py-0.5 shadow-md"
                onClick={(event) => event.stopPropagation()}
              >
                {caseMatches.length > 0 ? (
                  caseMatches.map((item, index) => (
                    <button
                      key={item.case_id}
                      type="button"
                      role="option"
                      aria-selected={index === caseIndex}
                      onMouseEnter={() => setCaseIndex(index)}
                      onClick={() => chooseCase(item)}
                      className={`flex w-full items-baseline gap-2 px-3 py-1.5 text-left transition ${index === caseIndex ? "bg-slate-200" : "hover:bg-slate-100"}`}
                    >
                      <span className="truncate text-xs font-semibold text-slate-900">
                        {item.title}
                      </span>
                      <span className="ml-auto shrink-0 font-mono text-[9px] text-slate-300">
                        {item.fall_id}
                      </span>
                    </button>
                  ))
                ) : (
                  <p className="px-3 py-2 text-xs text-slate-400">Kein Fall gefunden.</p>
                )}
              </div>
            )}
            {requiredIntakeFact && contextLength >= 20 && !showModeMenu && (
              <form
                className="ml-4 mt-5 max-w-2xl border-l border-slate-200 pl-5 sm:ml-8 sm:pl-6"
                onClick={(event) => event.stopPropagation()}
                onSubmit={(event) => {
                  event.preventDefault();
                  answerRequiredIntakeFact();
                }}
              >
                <p className="text-sm leading-6 text-slate-400">{requiredIntakeFact.question}</p>
                <div className="mt-2 flex items-end gap-3">
                  <textarea
                    autoFocus
                    value={requiredIntakeAnswer}
                    maxLength={1_500}
                    rows={1}
                    placeholder={requiredIntakeFact.placeholder}
                    onChange={(event) => setRequiredIntakeAnswer(event.target.value)}
                    className="min-h-10 flex-1 resize-y border-b border-slate-200 bg-transparent py-2 font-serif text-base leading-7 text-slate-700 outline-none placeholder:text-slate-300 focus:border-slate-500"
                  />
                  <button
                    type="submit"
                    disabled={!requiredIntakeAnswer.trim()}
                    className="min-h-10 rounded-full bg-slate-900 px-4 text-xs font-semibold text-white disabled:opacity-30"
                  >
                    Weiter
                  </button>
                </div>
              </form>
            )}
            {correctionMode && context.trim().length >= 4 && !showModeMenu && (
              <section
                aria-label="Tenor überarbeiten"
                className="ml-4 mt-6 max-w-2xl border-l border-slate-200 pl-5 sm:ml-8 sm:pl-6"
                onClick={(event) => event.stopPropagation()}
              >
                {activeArchive && (
                  <p className="mb-4 text-[11px] leading-5 text-slate-400">
                    Archivfassung vom{" "}
                    {new Date(activeArchive.created_at).toLocaleDateString("de-DE")}. Das Original
                    bleibt erhalten; die Überarbeitung wird als neue Fassung archiviert.
                  </p>
                )}
                {revisionHistory.map((instruction, index) => (
                  <div key={`${instruction}-${index}`} className="mb-4 flex justify-end">
                    <p className="max-w-[85%] rounded-2xl rounded-br-sm bg-slate-100 px-4 py-2.5 text-sm leading-6 text-slate-700">
                      {instruction}
                    </p>
                  </div>
                ))}
                <form
                  className="flex items-end gap-3"
                  onSubmit={(event) => {
                    event.preventDefault();
                    submitRevision();
                  }}
                >
                  <textarea
                    value={revisionInput}
                    maxLength={2_000}
                    rows={2}
                    aria-label="Änderungswunsch"
                    placeholder="Beschreibe, ob und wie der Tenor verändert werden soll …"
                    onChange={(event) => setRevisionInput(event.target.value)}
                    className="min-h-14 flex-1 resize-y rounded-2xl border border-slate-200 bg-white px-4 py-3 font-serif text-base leading-7 text-slate-700 outline-none placeholder:text-slate-300 focus:border-slate-400"
                  />
                  <button
                    type="submit"
                    disabled={!revisionInput.trim() || generating}
                    aria-label="Änderungswunsch senden"
                    className="grid size-11 shrink-0 place-items-center rounded-full bg-slate-950 text-white disabled:opacity-30"
                  >
                    {generating ? (
                      <Loader2 className="size-4 animate-spin" />
                    ) : (
                      <Send className="size-4" />
                    )}
                  </button>
                </form>
                {generationError && (
                  <p role="alert" className="mt-3 text-xs text-red-600">
                    {generationError}
                  </p>
                )}
              </section>
            )}
            {(clarificationTurns.length > 0 || currentQuestion || questionLoading) && (
              <div
                className="ml-4 mt-4 space-y-4 border-l border-slate-200 pl-5 sm:ml-8 sm:pl-6"
                onClick={(event) => event.stopPropagation()}
              >
                {clarificationTurns.map((turn, index) => (
                  <div key={`${turn.question.question_id}-${index}`}>
                    <p className="text-sm leading-6 text-slate-300">{turn.question.text}</p>
                    <p className="mt-1 font-serif text-base leading-7 text-slate-700">
                      {turn.answer}
                    </p>
                  </div>
                ))}

                {currentQuestion && (
                  <div>
                    <p className="text-sm leading-6 text-slate-300">{currentQuestion.text}</p>

                    {currentQuestion.answer_type === "yes_no" && (
                      <div className="mt-3 flex gap-2">
                        {(["Ja", "Nein"] as const).map((answer) => (
                          <button
                            key={answer}
                            type="button"
                            onClick={() => answerCurrentQuestion(answer)}
                            className="min-h-10 rounded-full border border-slate-200 px-5 text-sm text-slate-600 transition hover:border-slate-400 hover:text-slate-900"
                          >
                            {answer}
                          </button>
                        ))}
                      </div>
                    )}
                )}
              </div>
              {canRequestQuestions &&
                !currentQuestion &&
                !questionLoading &&
                !questionError &&
                clarificationTurns.length === 0 && (
                  <button
                    type="button"
                    onClick={() => void requestClarificationQuestion()}
                    className="flex items-center gap-2 rounded-full bg-slate-950 px-5 py-2.5 text-sm font-semibold text-white transition hover:bg-slate-800"
                  >
                    <Sparkles className="size-4" />
                    KI-Rückfragen starten
                  </button>
                )}
              {canGenerate && (
                <button
                  type="button"
                  onClick={generate}
                  disabled={generating}
                  aria-busy={generating}
                  className="flex items-center gap-2 rounded-full bg-slate-950 px-5 py-2.5 text-sm font-semibold text-white transition hover:bg-slate-800 disabled:opacity-60"
                >
                  {generating ? (
                    <Loader2 className="size-4 animate-spin" />
                  ) : (
                    <Sparkles className="size-4" />
                  )}
                  <span aria-live="polite">
                    {generating ? "KI erstellt zwei Entwürfe …" : "Generieren"}
                  </span>
                </button>
              )}
            </div>
          </div>
        </main>
      ) : (
        <main
          className={`mx-auto flex max-w-6xl flex-col px-6 py-8 md:py-6 ${
            selected
              ? "md:h-[calc(100dvh-2rem)] md:min-h-[38rem]"
              : "md:h-[calc(100dvh-8rem)] md:min-h-[30rem]"
          }`}
        >
          {selected ? (
            <>
              <div className="flex items-center justify-between gap-4">
                <button
                  type="button"
                  onClick={() => setSelected(null)}
                  className="flex items-center gap-2 text-sm text-slate-400 transition hover:text-slate-800"
                >
                  <ArrowLeft className="size-4" /> Beide Entwürfe
                </button>
                <span className="text-xs text-slate-300">Breite Lese- und Bearbeitungsansicht</span>
              </div>
              <div className="mx-auto mt-4 flex min-h-[64dvh] w-full max-w-5xl flex-1 flex-col md:min-h-0">
                <DraftChoice
                  title={selected === "precise" ? "Präzise" : "Technikneutral"}
                  draft={selected === "precise" ? preciseDraft : neutralDraft}
                  text={selected === "precise" ? preciseText : neutralText}
                  selected
                  onSelect={() => undefined}
                  onText={selected === "precise" ? setPreciseText : setNeutralText}
                  provenance={aiProvenance(proposalResponse, selected)}
                  expanded
                />
              </div>
              <div className="mt-4 flex min-h-11 items-center justify-center">
                <div className="text-center">
                  {archiveError && (
                    <p role="alert" className="mb-3 text-xs text-red-600">
                      {archiveError}
                    </p>
                  )}
                  <button
                    type="button"
                    onClick={() => void adoptSelected()}
                    disabled={savingArchive}
                    aria-busy={savingArchive}
                    className="inline-flex items-center gap-2 rounded-full bg-slate-950 px-6 py-2.5 text-sm font-semibold text-white disabled:opacity-60"
                  >
                    {savingArchive && <Loader2 className="size-4 animate-spin" />}
                    {savingArchive ? "Wird archiviert …" : "Entwurf übernehmen"}
                  </button>
                </div>
              </div>
            </>
          ) : (
            <>
              <h1 className="text-center font-sans text-sm font-medium text-slate-400">
                Wähle einen Entwurf
              </h1>
              <div className="mt-5 grid md:min-h-0 md:flex-1 md:grid-cols-2 md:divide-x md:divide-slate-100">
                <DraftChoice
                  title="Präzise"
                  draft={preciseDraft}
                  text={preciseText}
                  selected={false}
                  onSelect={() => setSelected("precise")}
                  onText={setPreciseText}
                  provenance={aiProvenance(proposalResponse, "precise")}
                />
                <DraftChoice
                  title="Technikneutral"
                  draft={neutralDraft}
                  text={neutralText}
                  selected={false}
                  onSelect={() => setSelected("neutral")}
                  onText={setNeutralText}
                  provenance={aiProvenance(proposalResponse, "neutral")}
                />
              </div>
              <div className="mt-4 min-h-11" />
            </>
          )}
        </main>
      )}
    </div>
  );
}

output.text:
import { Link } from "@tanstack/react-router";
import {
  ArrowLeft,
  Check,
  FileUp,
  Keyboard,
  Loader2,
  Mic,
  RotateCcw,
  Send,
  Sparkles,
  X,
} from "lucide-react";
import { useEffect, useMemo, useRef, useState } from "react";

import { composeDraft, getBlock, nextAutofillBlock, register } from "@/tenor-engine";
import type { Draft, Profile } from "@/tenor-types";
import { lottoDemoCases, type DemoCase } from "@/data/lottoDemoCases";
import {
  composeRevisionContext,
  extractLegalBases,
  filterModeCommands,
  inferFallgruppe,
  isTenor,
  modeCommands,
  nextRequiredIntakeFact,
  nextWrappedIndex,
  type RequiredIntakeAnswer,
  type WritingMode,
} from "@/lib/minimal-tenor-logic";
import {
  composeDictationText,
  mergeDictationSegments,
  type DictationSegments,
} from "@/lib/dictation";
import {
  createTenorProposals,
  createTenorQuestion,
  extractTenorPdf,
  listTenorArchiveEntries,
  saveTenorArchiveEntry,
  type TenorArchiveRecord,
  type TenorPdfExtraction,
  type TenorProposalResponse,
  type TenorQuestion,
} from "@/lib/tenor-api";
import {
  answeredQuestions,
  composeClarifiedContext,
  composePdfContext,
  formatSliderAnswer,
  type ClarificationTurn,
} from "@/lib/tenor-questions";
import { Slider } from "@/components/ui/slider";

const baseProfile: Profile = {
  profilId: "V-2026-014",
  schuldner: "die Beklagte",
  rechtsform: "GmbH",
  kanal: ["website"],
  url: "https://www.beispiel.de",
  adressat: "verbraucher",
  vertragstyp: "dauerschuldverhaeltnis",
  fallgruppe: "kuendigungsbutton",
  verstossModus: "vorhanden_unzureichend",
  rechtsgrundlage: ["§ 2 Abs. 1 UKlaG", "§ 312k Abs. 2 BGB", "§ 890 ZPO"],
  beanstandeterWortlaut: "",
  wirkung: "",
  bekannteUmgehungen: [],
  gestaltungsmerkmale: ["Gestaltung", "Wirkung"],
  anlage: "K 1",
};

type SpeechResult = { readonly transcript: string };
type SpeechResultList = {
  readonly length: number;
  [index: number]: { readonly isFinal: boolean; [index: number]: SpeechResult };
};
type SpeechEvent = { readonly resultIndex: number; readonly results: SpeechResultList };
type SpeechRecognitionInstance = {
  lang: string;
  continuous: boolean;
  interimResults: boolean;
  onresult: ((event: SpeechEvent) => void) | null;
  onend: (() => void) | null;
  start: () => void;
  stop: () => void;
};
type SpeechRecognitionConstructor = new () => SpeechRecognitionInstance;
function caseContext(selectedCase: DemoCase) {
  return `${selectedCase.fall_id}: ${selectedCase.title}. ${selectedCase.secondary}. ${selectedCase.explanation} Fundstelle: ${selectedCase.evidence.fundstelle}.`;
}

function profileFromContext(context: string, uploadedContract = false): Profile {
  const lower = context.toLowerCase();
  const fallgruppe = inferFallgruppe(lower, uploadedContract);
  const verstossModus =
    fallgruppe === "agb_klausel"
      ? "klausel_verwendet"
      : fallgruppe === "kuendigungsbutton"
        ? "vorhanden_unzureichend"
        : "irrefuehrend_gestaltet";
  const url = context.match(/https?:\/\/[^\s,;)]+/i)?.[0] ?? baseProfile.url;
  return {
    ...baseProfile,
    fallgruppe,
    verstossModus,
    url,
    kanal: /\bapp\b/i.test(context) ? ["website", "app"] : ["website"],
    beanstandeterWortlaut: fallgruppe === "agb_klausel" ? context.slice(0, 500) : "",
    wirkung: context.slice(0, 500),
  };
}

function legalBasesFor(fallgruppe: string) {
  if (fallgruppe === "agb_klausel") return ["§ 1 UKlaG"];
  if (fallgruppe === "irrefuehrende_werbung") return ["§ 5 UWG", "§ 8 Abs. 1 UWG"];
  if (fallgruppe === "consent_gestaltung") return ["§ 25 Abs. 1 TDDDG", "§ 2 Abs. 1 UKlaG"];
  if (fallgruppe === "dark_pattern_dsa") return ["Art. 25 DSA", "§ 2 Abs. 1 UKlaG"];
  return ["§ 312k Abs. 2 BGB", "§ 2 Abs. 1 UKlaG"];
}

function debtorFromContext(context: string) {
  const match = context.match(
    /\b([A-ZÄÖÜ][A-Za-zÄÖÜäöüß0-9&.,' -]{1,100}\s(?:GmbH|AG|UG|SE|KG|e\.\s?K\.))\b/,
  );
  return match?.[1]?.trim() ?? "die Antragsgegnerin";
}

function aiProvenance(response: TenorProposalResponse | null, strategy: "precise" | "neutral") {
  const proposal = response?.proposals.find((item) => item.strategy === strategy);
  if (!response || !proposal) return null;
  const knowledgeLabel = response.reference_version.includes("2026-08-24")
    ? "Wissensbasis 24.08.2026"
    : response.reference_version;
  return `OpenAI ${response.model} · ${knowledgeLabel} · ${proposal.source_ids.length} Quellenanker · nicht juristisch freigegeben`;
}

function referenceSummary(draft: Draft) {
  const references = [...new Set(draft.blockIds.flatMap((id) => getBlock(id).belegt_in))];
  return `${draft.blockIds.join(" · ")}  —  ${references
    .map((id) => {
      const tenor = register.tenore.find((item) => item.id === id);
      return tenor?.zitat_geprueft === true ? id : `${id} ungeprüft`;
    })
    .join(" · ")}`;
}

function DraftChoice({
  title,
  draft,
  text,
  selected,
  onSelect,
  onText,
  provenance,
  expanded = false,
}: {
  title: string;
  draft: Draft;
  text: string;
  selected: boolean;
  onSelect: () => void;
  onText: (text: string) => void;
  provenance?: string | null;
  expanded?: boolean;
}) {
  return (
    <div
      className={`flex min-w-0 flex-col ${
        expanded
          ? "min-h-[64dvh] flex-1 px-0 py-2 md:min-h-0"
          : "px-1 py-4 md:min-h-0 md:px-6 md:py-1"
      }`}
    >
      <button
        type="button"
        onClick={onSelect}
        className={`flex items-center gap-3 text-left ${expanded ? "min-h-11" : ""}`}
      >
          error instanceof Error ? error.message : "Das Tenorarchiv konnte nicht geladen werden.",
        );
      })
      .finally(() => {
        if (!cancelled) setArchiveLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [initialArchiveId]);

  useEffect(() => {
    if (!correctionMode || generated || context.trim().length < 4) {
      setSuggestion(null);
      return;
    }
    const timer = window.setTimeout(
      () => setSuggestion(nextAutofillBlock(profile, acceptedIds)),
      800,
    );
    return () => window.clearTimeout(timer);
  }, [acceptedIds, context, correctionMode, generated, profile]);

  useEffect(() => {
    setCommandIndex(0);
  }, [slashQuery]);

  useEffect(() => {
    setCaseIndex(0);
  }, [normalizedCaseQuery]);

  useEffect(() => {
    const input = contextInput.current;
    if (!input) return;
    input.style.height = "0px";
    input.style.height = `${Math.max(input.scrollHeight, 36)}px`;
  }, [context, pdf]);

  useEffect(() => {
    if (previousSourceContext.current === sourceContext) return;
    previousSourceContext.current = sourceContext;
    questionSession.current += 1;
    setClarificationTurns([]);
    setCurrentQuestion(null);
    setQuestionLoading(false);
    setClarificationReady(false);
    setQuestionError("");
    setTextAnswer("");
    setCustomChoiceOpen(false);
    setRequiredIntakeAnswers([]);
    setRequiredIntakeAnswer("");
  }, [sourceContext]);

  useEffect(
    () => () => {
      dictationSession.current += 1;
      pdfSession.current += 1;
      speech.current?.stop();
    },
    [],
  );

  const acceptPdf = async (file?: File) => {
    if (!file) return;
    const session = pdfSession.current + 1;
    pdfSession.current = session;
    if (file.type !== "application/pdf" && !file.name.toLowerCase().endsWith(".pdf")) {
      setPdf(null);
      setPdfExtraction(null);
      setPdfLoading(false);
      setPdfError("Bitte eine PDF-Datei auswählen.");
      return;
    }
    if (file.size > 10 * 1024 * 1024) {
      setPdf(file);
      setPdfExtraction(null);
      setPdfLoading(false);
      setPdfError("Die PDF-Datei darf höchstens 10 MB groß sein.");
      return;
    }
    setPdf(file);
    setPdfExtraction(null);
    setPdfLoading(true);
    setPdfError("");
    setGenerated(false);
    setGenerationError("");
    try {
      const extraction = await extractTenorPdf(file);
      if (pdfSession.current !== session) return;
      setPdfExtraction(extraction);
    } catch (error) {
      if (pdfSession.current !== session) return;
      setPdfError(
        error instanceof Error ? error.message : "Der PDF-Text konnte nicht gelesen werden.",
      );
    } finally {
      if (pdfSession.current === session) setPdfLoading(false);
    }
  };

  const removePdf = () => {
    pdfSession.current += 1;
    setPdf(null);
    setPdfExtraction(null);
    setPdfLoading(false);
    setPdfError("");
  };

  const selectMode = (nextMode: WritingMode) => {
    const contextWithoutCommand = context.replace(/(?:^|\s)\/[^\s]*$/, "").trimEnd();
    setMode(nextMode);
    setSelectedCase(null);
    setActiveArchive(null);
    setRevisionInput("");
    setRevisionHistory([]);
    setContext(nextMode === "fälle" ? "" : contextWithoutCommand);
    setCommandIndex(0);
    setCaseIndex(0);
    setGenerated(false);
    setSuggestion(null);
    setGenerationError("");
    window.requestAnimationFrame(() => contextInput.current?.focus());
  };

  const chooseCase = (item: DemoCase) => {
    setMode("fälle");
    setSelectedCase(item);
    setActiveArchive(null);
    setCaseIndex(0);
    setContext(caseContext(item));
    setGenerated(false);
    setSuggestion(null);
    setGenerationError("");
    window.requestAnimationFrame(() => contextInput.current?.focus());
  };

  const toggleDictation = () => {
    if (dictating) {
      speech.current?.stop();
      setDictating(false);
      return;
    }
    const browserWindow = window as typeof window & {
      SpeechRecognition?: SpeechRecognitionConstructor;
      webkitSpeechRecognition?: SpeechRecognitionConstructor;
    };
    const Recognition = browserWindow.SpeechRecognition ?? browserWindow.webkitSpeechRecognition;
    if (!Recognition) {
      setDictationNotice("Diktat wird von diesem Browser nicht unterstützt.");
      return;
    }
    const recognition = new Recognition();
    const session = dictationSession.current + 1;
    dictationSession.current = session;
    dictationBase.current = context;
    dictationSegments.current = {};
    recognition.lang = "de-DE";
    recognition.continuous = true;
    recognition.interimResults = true;
    recognition.onresult = (event) => {
      if (dictationSession.current !== session) return;
      const updates = [];
      for (let index = event.resultIndex; index < event.results.length; index += 1) {
        const result = event.results[index];
        updates.push({
          index,
          transcript: result?.[0]?.transcript ?? "",
          isFinal: result?.isFinal ?? false,
        });
      }
      dictationSegments.current = mergeDictationSegments(dictationSegments.current, updates);
      setContext(composeDictationText(dictationBase.current, dictationSegments.current));
    };
    recognition.onend = () => {
      if (dictationSession.current !== session) return;
      speech.current = null;
      setDictating(false);
    };
    speech.current = recognition;
    setDictationNotice("");
    setDictating(true);
    recognition.start();
  };

  const acceptSuggestion = () => {
    if (!suggestion) return;
    setContext((current) => `${current.trim()} ${suggestion.text.replace(/\s+/g, " ").trim()}`);
    setAcceptedIds((current) => [...current, suggestion.id]);
    setSuggestion(null);
  };

  const requestClarificationQuestion = async (turns = clarificationTurns) => {
    if (sourceContext.length < 20 || questionLoading || pdfLoading) return;
    const session = questionSession.current + 1;
    questionSession.current = session;
    setQuestionLoading(true);
    setQuestionError("");
    setCurrentQuestion(null);
    try {
      const response = await createTenorQuestion({
        context: factualContext,
        fallgruppe: profile.fallgruppe,
        answered_questions: answeredQuestions(turns),
      });
      if (questionSession.current !== session) return;
      if (response.ready_to_generate) {
        setClarificationReady(true);
        return;
      }
      if (!response.question) throw new Error("Die KI hat keine Rückfrage geliefert.");
      setCurrentQuestion(response.question);
      setTextAnswer("");
      setCustomChoiceOpen(false);
      if (response.question.slider) {
        const { minimum, maximum, step } = response.question.slider;
        const steps = Math.floor((maximum - minimum) / step);
        setSliderAnswer(minimum + Math.floor(steps / 2) * step);
      }
    } catch (error) {
      if (questionSession.current !== session) return;
      setQuestionError(
        error instanceof Error ? error.message : "Die KI-Rückfrage konnte nicht erzeugt werden.",
      );
    } finally {
      if (questionSession.current === session) setQuestionLoading(false);
    }
  };

  const answerCurrentQuestion = (answer: string) => {
    const cleanedAnswer = answer.trim();
    if (!currentQuestion || !cleanedAnswer || questionLoading) return;
    const nextTurns = [...clarificationTurns, { question: currentQuestion, answer: cleanedAnswer }];
    setClarificationTurns(nextTurns);
    setCurrentQuestion(null);
    setTextAnswer("");
    setCustomChoiceOpen(false);
    void requestClarificationQuestion(nextTurns);
  };

  const answerRequiredIntakeFact = () => {
    const answer = requiredIntakeAnswer.trim();
    if (!requiredIntakeFact || !answer) return;
    setRequiredIntakeAnswers((current) => [
      ...current.filter((item) => item.id !== requiredIntakeFact.id),
      { ...requiredIntakeFact, answer },
    ]);
    setRequiredIntakeAnswer("");
  };

  const generateProposals = async (generationContext: string) => {
    if (generating || generationContext.trim().length < 4) return;
    setGenerating(true);
    setGenerationError("");
    setSuggestion(null);
    setLastGenerationContext(generationContext);
    try {
      const legalBases = extractLegalBases(generationContext);
      const legalBasisStillOpen = requiredIntakeAnswers.some(
        (item) => item.id === "rechtsgrundlagen" && extractLegalBases(item.answer).length === 0,
      );
      const response = await createTenorProposals({
        fall_id: activeArchive?.fall_id ?? selectedCase?.fall_id ?? "TENOR-ENTWURF",
        schuldner: activeArchive?.schuldner ?? debtorFromContext(generationContext),
        fundstelle:
          selectedCase?.url ??
          generationContext.match(/https?:\/\/[^\s,;)]+/i)?.[0] ??
          (pdfExtraction
            ? `Hochgeladenes Vertragsdokument: ${pdfExtraction.filename}`
            : "Vom Nutzer beschriebene Fundstelle"),
        context: generationContext,
        fallgruppe: profile.fallgruppe,
        rechtsgrundlagen:
          legalBases.length > 0
            ? legalBases
            : legalBasisStillOpen
              ? ["Rechtsgrundlage noch durch Menschen zu prüfen"]
              : legalBasesFor(profile.fallgruppe),
      });
      const precise = response.proposals.find((item) => item.strategy === "precise");
      const neutral = response.proposals.find((item) => item.strategy === "neutral");
      if (!precise || !neutral) throw new Error("Die KI hat nicht beide Entwürfe geliefert.");
      setProposalResponse(response);
      setPreciseText(precise.text);
      setNeutralText(neutral.text);
      setSelected(null);
      setGenerated(true);
    } catch (error) {
      setProposalResponse(null);
      setGenerationError(
        error instanceof Error ? error.message : "Die KI-Entwürfe konnten nicht erzeugt werden.",
      );
    } finally {
      setGenerating(false);
    }
  };

  const generate = () => {
    if (!canGenerate) return;
    void generateProposals(clarifiedContext);
  };

  const submitRevision = () => {
    const instruction = revisionInput.trim();
    if (!instruction || generating || context.trim().length < 4) return;
    const revisionContext = composeRevisionContext(
      context,
      instruction,
      activeArchive?.context ?? "",
    );
    setRevisionHistory((current) => [...current, instruction]);
            )}
            {mode === "fälle" && !selectedCase && !showModeMenu && (
              <div
                role="listbox"
                aria-label="Fall auswählen"
                className="ml-14 mt-1 max-w-sm overflow-hidden rounded-lg border border-slate-200 bg-white py-0.5 shadow-md"
                onClick={(event) => event.stopPropagation()}
              >
                {caseMatches.length > 0 ? (
                  caseMatches.map((item, index) => (
                    <button
                      key={item.case_id}
                      type="button"
                      role="option"
                      aria-selected={index === caseIndex}
                      onMouseEnter={() => setCaseIndex(index)}
                      onClick={() => chooseCase(item)}
