  provenance?: string | null;
  expanded?: boolean;
}) {
  return (
    <div
      className={`flex min-w-0 flex-col ${
        expanded
          ? "min-h-[64dvh] flex-1 px-0 py-2 md:min-h-0"
          : "px-1 py-4 md:min-h-0 md:px-6 md:py-1"
      }`}
